// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;

    function setUp() public { c = new airdrop(); }

    function testFuzz_property(address from, address to1, address to2, uint256 v, bool fail) public {
        vm.assume(from != address(0));
        address[] memory tos = new address[](2);
        tos[0] = to1;
        tos[1] = to2;

        if (!fail) {
            // all underlying calls succeed => c.transfer must return true
            TokenMock tok = new TokenMock(false);
            bool ok = c.transfer(from, address(tok), tos, v);
            assertTrue(ok);
        } else {
            // underlying call fails => c.transfer reverts (require) — same rule for both versions
            TokenMock tok = new TokenMock(true);
            bool reverted = false;
            try c.transfer(from, address(tok), tos, v) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assertTrue(reverted);
        }
    }
}

contract TokenMock {
    bool private _fail;
    constructor(bool f) { _fail = f; }
    function transferFrom(address, address, uint256) external view returns (bool) {
        if (_fail) revert();
        return true;
    }
}
